31	pub(crate) fn render_tab_bar(
32	    tabs: &[SelectionTab],
33	    active_idx: usize,
34	    area: Rect,
35	    buf: &mut Buffer,
36	) {
37	    for (offset, line) in tab_bar_lines(tabs, active_idx, area.width)
38	        .into_iter()
39	        .take(area.height as usize)
40	        .enumerate()
41	    {
42	        line.render(
43	            Rect {
44	                x: area.x,
45	                y: area.y.saturating_add(offset as u16),
46	                width: area.width,
47	                height: 1,
48	            },
49	            buf,
50	        );
51	    }
52	}
