        name: name.to_string(),
        description: Some(description.to_string()),
        is_disabled: true,
        ..Default::default()
    }
}

fn is_curated_marketplace(marketplace: &PluginMarketplaceEntry) -> bool {
    marketplace.name == OPENAI_CURATED_MARKETPLACE_NAME
}

/// Stable tab identifier for a marketplace, derived from its file system path so
/// marketplaces that share a display name remain individually addressable.
fn marketplace_tab_id(marketplace: &PluginMarketplaceEntry) -> String {
    format!("marketplace:{}", marketplace.path.to_string_lossy())
}

/// Compute tab labels for the ordered marketplace list, appending `Name (K/N)`
/// disambiguation suffixes when multiple marketplaces share the same label.
fn disambiguated_marketplace_tab_labels(
    marketplaces: &[&PluginMarketplaceEntry],
) -> Vec<String> {
    let base_labels: Vec<String> = marketplaces
        .iter()
        .map(|marketplace| {
            if is_curated_marketplace(marketplace) {
                "OpenAI Curated".to_string()
            } else {
                marketplace_display_name(marketplace)
            }
        })
        .collect();

    let mut totals: HashMap<&str, usize> = HashMap::new();
    for label in &base_labels {
        *totals.entry(label.as_str()).or_default() += 1;
    }

    let mut seen: HashMap<&str, usize> = HashMap::new();
    base_labels
        .iter()
        .map(|label| {
            let total = totals.get(label.as_str()).copied().unwrap_or(1);
            if total > 1 {
                let occurrence = seen.entry(label.as_str()).or_default();
                *occurrence += 1;
                format!("{label} ({occurrence}/{total})")
            } else {
                label.clone()
            }
        })
        .collect()
